import envConfigs from '@cetus/types/src/config/envConfigs'

export function useJump2Dex() {
  const { cetus_clmm_site } = envConfigs

  const back2Dex = () => {
    window.open(`${cetus_clmm_site}`, '_self')
  }

  const jump2Swap = (from: string, to: string) => {
    window.open(`${cetus_clmm_site}/swap?from=${from}&to=${to}`, '_self')
  }

  const jump2Pool = (poolAddress: string) => {
    window.open(`${cetus_clmm_site}/liquidity/deposit?poolAddress=${poolAddress}`, '_self')
  }
  return {
    back2Dex,
    jump2Swap,
    jump2Pool
  }
}
